import{_ as a,o as d,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Закон о Гарантии Образования","description":"","frontmatter":{},"headers":[],"relativePath":"ru/43-教育保障法.md","filePath":"ru/43-教育保障法.md"}'),l={name:"ru/43-教育保障法.md"};function e(o,t,h,n,s,b){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="закон-о-гарантии-образования" tabindex="-1">Закон о Гарантии Образования <a class="header-anchor" href="#закон-о-гарантии-образования" aria-label="Permalink to &quot;Закон о Гарантии Образования&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>43</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Право на образование, Симбиотическое образование, Передача культивации, Обучение в течение всей жизни, Образовательная справедливость</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Закон о Гарантии Образования</em> — один из пяти вспомогательных законов Симбиотической Цивилизации Якоря. Он направлен на гарантию права на образование всех жизней во Вселенной Хэнъюань, создание образовательной системы с «симбиотической эволюцией» как ключевой концепцией и обеспечение совместного продвижения Десяти Тысяч Рас знаниями и кадрами.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Образовательная справедливость</td><td>Все жизни, независимо от расы, культивации или происхождения, имеют равные образовательные возможности</td></tr><tr><td>Обучение по способностям</td><td>Уважение различий талантов и выбора путей эволюции каждой жизни, предоставление индивидуальных образовательных планов</td></tr><tr><td>Единство знания и действия</td><td>Сочетание теоретических знаний и практической культивации; против оторванного от реальности пустословия</td></tr><tr><td>Открытость и общий доступ</td><td>Образовательные ресурсы открыты всему обществу; базовые методы Трёхсот Изначальных Систем Культивации преподаются бесплатно</td></tr><tr><td>Обучение в течение всей жизни</td><td>Образование пронизывает весь процесс жизни, поддерживая непрерывное обучение и повышение способностей на всех этапах</td></tr><tr><td>Культурный плюрализм</td><td>Уважение культурных традиций всех рас, поощрение плюралистического культурного обмена и взаимного обучения</td></tr></tbody></table><h2 id="ii-правовые-гарантии-права-на-образование" tabindex="-1">II. Правовые гарантии права на образование <a class="header-anchor" href="#ii-правовые-гарантии-права-на-образование" aria-label="Permalink to &quot;II. Правовые гарантии права на образование&quot;">​</a></h2><p>Настоящий Закон прямо устанавливает, что право на образование — основное право, предоставленное каждой жизни Симбиотической Конституцией, и что государство и цивилизация обязаны гарантировать реализацию этого права:</p><ol><li><strong>Бесплатное базовое образование</strong>: все жизни имеют право на бесплатное базовое образование, включая общие знания, базовые методы культивации, концепции симбиотической цивилизации и т.д. Срок обучения — от шести до двенадцати лет, корректируется по циклу развития каждой расы.</li><li><strong>Бесплатное введение в культивацию</strong>: базовые методы Трёхсот Изначальных Систем Культивации открыты для всех жизней бесплатно; никакая организация или индивид не вправе присваивать базовые методы культивации в частную собственность и преподавать за плату.</li><li><strong>Равные возможности продвижения</strong>: образовательные учреждения всех уровней не должны устанавливать дискриминационные условия по признаку расы, культивации или происхождения при приёме; критерии приёма открыты и прозрачны.</li><li><strong>Гарантии специального образования</strong>: предоставление адаптированных специальных образовательных ресурсов и поддержки дистанционного образования таким группам, как жизни с ограниченными возможностями, жизни иных рас, жизни отдалённых плоскостей.</li><li><strong>Институт образовательной помощи</strong>: предоставление грантов, стипендий и беспроцентных кредитов учащимся с финансовыми трудностями, гарантируя, что никто не потеряет образовательные возможности по экономическим причинам.</li></ol><h2 id="iii-архитектура-образовательнои-системы" tabindex="-1">III. Архитектура образовательной системы <a class="header-anchor" href="#iii-архитектура-образовательнои-системы" aria-label="Permalink to &quot;III. Архитектура образовательной системы&quot;">​</a></h2><p>Образовательная система Симбиотической Цивилизации Якоря делится на четыре уровня, органично связанных между собой:</p><table tabindex="0"><thead><tr><th>Уровень</th><th>Название</th><th>Цель</th><th>Срок обучения</th></tr></thead><tbody><tr><td>Первый уровень</td><td>Просветительское образование</td><td>Формирование базовых когнитивных способностей и симбиотического сознания; преподавание базовых методов культивации</td><td>3-6 лет</td></tr><tr><td>Второй уровень</td><td>Базовое образование</td><td>Системное изучение общих знаний и теории культивации; выявление направлений талантов индивида</td><td>6-9 лет</td></tr><tr><td>Третий уровень</td><td>Профессиональное образование</td><td>Углублённое изучение и практика в выбранной системе культивации или профессиональной области</td><td>3-10 лет</td></tr><tr><td>Четвёртый уровень</td><td>Высшая стажировка</td><td>Передовые исследования и инновационная стажировка для продвинутых культиваторов и исследователей</td><td>Без ограничений</td></tr></tbody></table><p>Кроме того, учреждена «Система сети наставников»: культиваторы, достигшие определённой стадии культивации, обязаны в пределах своих возможностей наставлять начинающих культиваторов; вклад наставничества засчитывается в объём вклада Механизма Совместного Подряда и получает соответствующее распределение ресурсов.</p><h2 id="iv-образовательные-учреждения-и-преподаватели" tabindex="-1">IV. Образовательные учреждения и преподаватели <a class="header-anchor" href="#iv-образовательные-учреждения-и-преподаватели" aria-label="Permalink to &quot;IV. Образовательные учреждения и преподаватели&quot;">​</a></h2><ul><li><strong>Государственные образовательные учреждения</strong>: учреждаются государством или сообществом цивилизации, выполняют бесплатное базовое образование и общественные образовательные услуги, финансирование обеспечивается общественным фондом накопления.</li><li><strong>Частные образовательные учреждения</strong>: учреждаются общественными силами в соответствии с законом; могут взимать разумную плату, но обязаны принимать надзор компетентных органов образования и не должны заниматься ложной рекламой и хищническим взиманием платы.</li><li><strong>Культивационные секты</strong>: традиционные культивационные организации после регистрации могут действовать как профессиональные образовательные учреждения; обязаны соблюдать образовательное законодательство и не вправе закрыто монополизировать культивационные ресурсы.</li><li><strong>Права и обязанности преподавателей</strong>: преподаватели пользуются правами на академическую свободу, разумное вознаграждение, профессиональное обучение и т.д., а также несут обязанности обучать и воспитывать, быть примером, охранять конфиденциальность учащихся и т.д.</li></ul><h2 id="v-содержание-образования-и-стандарты-программ" tabindex="-1">V. Содержание образования и стандарты программ <a class="header-anchor" href="#v-содержание-образования-и-стандарты-программ" aria-label="Permalink to &quot;V. Содержание образования и стандарты программ&quot;">​</a></h2><p>Содержание образования должно соответствовать следующим требованиям:</p><ol><li>Включать ключевые концепции симбиотической цивилизации и образование против хищничества, формируя симбиотическое сознание обучающихся.</li><li>Включать базовые теории и вводные методы Трёхсот Изначальных Систем Культивации.</li><li>Включать общие научные знания: космические законы, знания о плоскостях, науки о жизни и т.д.</li><li>Включать историю и культуру Десяти Тысяч Рас, способствуя взаимопониманию и уважению между расами.</li><li>Включать практическую культивацию и социальное служение, формируя способность единства знания и действия.</li><li>Запрещать распространение хищнических культивационных концепций и дискриминационных идей.</li></ol><h2 id="vi-юридическая-ответственность" tabindex="-1">VI. Юридическая ответственность <a class="header-anchor" href="#vi-юридическая-ответственность" aria-label="Permalink to &quot;VI. Юридическая ответственность&quot;">​</a></h2><p>Действия, нарушающие положения настоящего Закона, в зависимости от тяжести обстоятельств несут следующую ответственность:</p><ul><li>Отказ или препятствование получению обязательного образования жизнями школьного возраста — предписание исправить и наказание.</li><li>Образовательные учреждения, незаконно взимающие плату или занимающиеся ложной рекламой, — предписание вернуть плату и штраф; при серьёзных обстоятельствах — аннулирование лицензии на образовательную деятельность.</li><li>Преподаватели, применяющие телесные наказания или дискриминирующие учащихся, — взыскание; при серьёзных обстоятельствах — лишение педагогической квалификации и привлечение к ответственности.</li><li>Присвоение общественных культивационных ресурсов в частную собственность или монополизация платы — конфискация незаконного дохода и штраф.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон о Гарантии Образования</em> — образовательная практика философии «дорога для каждого» Симбиотической Цивилизации Якоря. Гарантируя право на образование, выстраивая многоуровневую образовательную систему и открывая культивационные ресурсы, он обеспечивает каждой жизни получение подходящего пути эволюции, бесперебойно снабжая совместное продвижение Десяти Тысяч Рас знаниями и кадрами.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>37-共生教育体系 (Симбиотическая образовательная система)</li><li>10-三百套本源修炼体系总览 (Обзор Трёхсот Изначальных Систем Культивации)</li><li>08-人人有路保障体系 (Система Гарантии Дороги Для Каждого)</li></ul>',25)])])}const _=a(l,[["render",e]]);export{c as __pageData,_ as default};
